// Generated by vespyr — do not edit. Hook IDs: .agents/hooks/hooks.json
// OpenCode V2 plugin API (verified 2026-11-19): Plugin.define + ctx.tool.hook /
// ctx.session.hook / ctx.event.subscribe. There is no 'hooks' key in opencode.json.
import { Plugin } from "@opencode/plugin";
import { spawnSync } from "node:child_process";

function run(id, payload, { blocking = false } = {}) {
  const result = spawnSync("node", [".agents/scripts/hooks/" + id + ".js"], {
    cwd: process.cwd(),
    input: JSON.stringify(payload),
    encoding: "utf8",
  });
  if (result.error || result.status === null) {
    if (blocking) {
      throw new Error(result.error ? result.error.message : "Vespyr hook " + id + " failed closed");
    }
    return;
  }
  if (result.status === 2) {
    throw new Error(result.stderr.trim() || "Vespyr hook " + id + " blocked this action");
  }
}

export default Plugin.define({
  id: "vespyr-hooks",
  setup(ctx) {
    ctx.tool.hook("execute.before", (event) => {
      const tool = String(event.tool || "").toLowerCase();
      const agentType = event.agent || event.agentType || process.env.VESPYR_HOOK_AGENT || "developer";
      const payload = {
        hook_event_name: "PreToolUse",
        agent_type: agentType,
        tool_name: tool === "bash" || tool === "shell" ? "Bash" : tool === "edit" || tool === "apply_patch" ? "Edit" : tool === "write" || tool === "create" ? "Write" : tool,
        tool_input: event.input,
        cwd: process.cwd(),
      };
      if (payload.tool_name === "Bash") {
        run("pre-bash-safety", payload, { blocking: true });
        run("pre-bash-tmux", payload);
        run("pre-bash-delegation", payload, { blocking: true });
      } else if (payload.tool_name === "Edit" || payload.tool_name === "Write") {
        run("pre-edit-delegation", payload, { blocking: true });
      }
    });
    ctx.tool.hook("execute.after", (event) => {
      const tool = String(event.tool || "").toLowerCase();
      if (tool !== "edit" && tool !== "write" && tool !== "apply_patch") return;
      const payload = { hook_event_name: "PostToolUse", tool_name: "Edit", tool_input: event.input, cwd: process.cwd() };
      run("post-edit-format", payload);
      run("post-edit-dedupe", payload);
    });
    ctx.session.hook("context", () => {
      run("session-start-load-context", { hook_event_name: "SessionStart", cwd: process.cwd() });
      run("session-start-detect-package-manager", { hook_event_name: "SessionStart", cwd: process.cwd() });
    });
    ctx.session.hook("compaction", () => {
      run("pre-compact-save-state", { hook_event_name: "PreCompact", cwd: process.cwd() });
    });
    ctx.event.subscribe().then(async (events) => {
      for await (const event of events) {
        if (event.type === "session.idle") {
          run("stop-check-console-log", { hook_event_name: "Stop", cwd: process.cwd() });
          run("stop-session-end", { hook_event_name: "Stop", cwd: process.cwd() });
        }
      }
    }).catch(() => {});
  },
});
